      const targetTags = String(diagnostics.contentAppShellLoginMatrixTargetTags || '')
        .split(',')
        .map((tag) => tag.trim())
        .filter((tag) => tag);
      const observedTags = targetTags.filter((tag) => !!customElements.get(tag));
