      diagnostics.contentAppShellLoginMatrixImportTimedOut = true;
      diagnostics.contentAppShellLoginMatrixImportResult = 'browser-import-timeout';
      diagnostics.contentAppShellLoginMatrixFailureLayer = 'browser-import-timeout';
      diagnostics.contentAppShellLoginMatrixObservedTags = observedTags.join(',');
      diagnostics.contentAppShellLoginMatrixMissingTags = missingTags.join(',');
      diagnostics.contentAppShellLoginMatrixRemainingBlockers = missingTags.join(',');
